# Phan C: muc 4 — 5 phong cach
C = []
P = C.append

P(('h2','4. Mẫu thiết kế văn phòng 70m2 theo phong cách'))
P(('p','Phong cách không chỉ là chuyện đẹp xấu. Ở mặt bằng 70m², phong cách quyết định luôn cả số chỗ ngồi: phong cách nào dùng nhiều vách đặc và nội thất khối lớn thì mất chỗ, phong cách nào dùng kính và nội thất nhẹ thì giữ được chỗ. Năm phong cách dưới đây được doanh nghiệp chọn nhiều nhất cho diện tích này — kèm con số cụ thể cho thấy mỗi phong cách giữ lại hay lấy đi bao nhiêu chỗ ngồi.'))

# ---------- 4.1 HIEN DAI ----------
P(('h3','4.1. Mẫu thiết kế văn phòng 70m2 phong cách hiện đại'))
P(('p','Phong cách hiện đại đi theo đường nét thẳng, mặt phẳng gọn, không hoa văn trang trí. Vật liệu chủ đạo là kính, kim loại sơn tĩnh điện và gỗ công nghiệp phủ melamine hoặc laminate. Bảng màu giữ ở tông trung tính — trắng, xám, đen — và chỉ dùng màu thương hiệu ở một vài điểm nhấn như tường lễ tân hoặc mặt vách phòng họp. Đây là phong cách an toàn nhất cho văn phòng 70m2 vì hợp với hầu hết loại hình doanh nghiệp và dễ thay đổi về sau.'))
P(('lead','Ưu điểm với mặt bằng 70m²'))
P(('ul',[
  '**Giữ được chỗ ngồi.** Vách kính thay vách thạch cao giúp phòng họp và phòng giám đốc không cắt vụn tầm nhìn, cả sàn vẫn cảm giác liền mạch.',
  '**Nội thất mỏng, chiếm ít sàn.** Bàn chân sắt hộp và tủ treo tường thay tủ đứng giải phóng diện tích sàn cho lối đi.',
  '**Dễ nâng cấp từng phần.** Đổi màu ghế, đổi mặt bàn là văn phòng đã khác, không phải đập vách.',
  '**Chi phí ở mức giữa.** Vật liệu công nghiệp có sẵn theo mô-đun nên ít phát sinh gia công tại công trường.']))
P(('p','So sánh trực tiếp trên cùng mặt bằng 70m²: một phòng họp 6 chỗ làm bằng vách thạch cao dày 10cm hai lớp chiếm khoảng 12m² tính cả tường; cũng phòng họp đó làm bằng vách kính khung nhôm dày 5cm chỉ chiếm khoảng 10m². Hai mét vuông chênh lệch đó đúng bằng một chỗ ngồi. Nhân với hai phòng kín — phòng họp và phòng giám đốc — là giữ lại được hai chỗ ngồi mà không phải bỏ phòng nào. Đó là lý do phong cách hiện đại thường cho ra mặt bằng 12 – 13 chỗ, trong khi phương án vách đặc chỉ còn 10 – 11 chỗ.'))
P(('img','a70-04','Phòng họp phong cách hiện đại trong văn phòng 70m2: vách kính trong suốt, bàn họp gỗ sáng màu, cây xanh trang trí đơn giản (Nguồn: Internet)'))
P(('img','a70-16','Phòng giám đốc 8 – 12m² trong văn phòng 70m2 phong cách hiện đại, tủ âm tường chạy suốt một mặt để giải phóng sàn'))
P(('img','b80-07','Vách kính chia phòng họp mà không chặn ánh sáng — cách giữ chỗ ngồi hiệu quả nhất cho văn phòng 70m2 (Ảnh tham khảo)'))
P(('img','b80-13','Gỗ sẫm màu và đá nhân tạo ở khu tiếp khách tạo cảm giác tin cậy ngay từ phút đầu (Ảnh tham khảo)'))
P(('img','b80-19','Bàn kê đối xứng hai dãy, đèn thả lệch trục để màn hình không bị bóng đổ (Ảnh tham khảo)'))

# ---------- 4.2 TOI GIAN ----------
P(('h3','4.2. Mẫu thiết kế văn phòng 70m2 phong cách tối giản (Minimalism)'))
P(('p','Tối giản không phải là làm ít đồ cho rẻ, mà là bỏ hết những gì không có công năng. Trên mặt bằng 70m2, điều đó có nghĩa: không phào chỉ, không trần giật cấp nhiều lớp, không tủ trang trí. Đồ lưu trữ giấu vào tường hoặc gom vào một hệ tủ duy nhất. Bảng màu thường chỉ hai đến ba màu, phần lớn là trắng, be và gỗ sáng, cộng đúng một màu nhấn.'))
P(('lead','Ưu điểm với mặt bằng 70m²'))
P(('ul',[
  '**Không gian không bị rối mắt.** Mắt người đọc được "khoảng thở" nên 70m² trông rộng hơn diện tích thật.',
  '**Tiết kiệm chi phí thật.** Bỏ phào chỉ và trần giật cấp cắt được phần thi công tốn công nhất tại công trường.',
  '**Dễ giữ gọn về sau.** Ít bề mặt trang trí đồng nghĩa ít chỗ để đồ bừa bộn tích tụ.',
  '**Hợp với doanh nghiệp thuê ngắn hạn.** Hạng mục chủ yếu là nội thất rời, hết hạn thuê tháo mang đi được.']))
P(('p','Phần trang trí thuần túy — phào chỉ, trần giật cấp, tủ trưng bày — thường chiếm khoảng 10 – 15% tổng chi phí thi công một văn phòng. Với văn phòng 70m² làm gói tiêu chuẩn (280 – 490 triệu), bỏ hẳn nhóm hạng mục này tiết kiệm khoảng 28 – 70 triệu, đủ để nâng cấp toàn bộ ghế làm việc hoặc bù cho một phòng họp vách kính. Về diện tích, thay ba tủ đứng cao 2m bằng một hệ tủ âm tường trả lại khoảng 2 – 3m² sàn, tức là thêm được một chỗ ngồi.'))
P(('img','a70-05','Văn phòng 70m2 phong cách tối giản: bàn dãy gỗ sáng, vách kính, không tủ trang trí chiếm sàn'))
P(('img','a70-06','Văn phòng tối giản với tông trắng be chủ đạo kết hợp sàn gỗ sáng màu, hoàn toàn chú trọng vào công năng (Nguồn: Internet)'))
P(('img','b80-10','Tối giản: màu trung tính, bề mặt gọn, hệ lưu trữ giấu hết vào tường (Ảnh tham khảo)'))
P(('img','b80-11','Một mảng tường sẫm duy nhất làm điểm nhấn, phần còn lại giữ trắng để mặt bằng trông rộng hơn (Ảnh tham khảo)'))
P(('img','b80-36','Giữ bố cục tối giản nhưng thay tranh trang trí bằng cây xanh để không gian có sức sống (Ảnh tham khảo)'))

# ---------- 4.3 XANH ----------
P(('h3','4.3. Mẫu thiết kế văn phòng 70m2 phong cách xanh (Eco / Green Office)'))
P(('p','Phong cách xanh đưa cây xanh, vật liệu tự nhiên và ánh sáng trời thành thành phần chính của thiết kế chứ không phải đồ trang trí thêm vào cuối. Trên mặt bằng 70m2, cách làm phổ biến là dùng bồn cây và giá cây thay cho vách ngăn, kết hợp lam gỗ, sàn gỗ và rèm sáng màu. Đây cũng là phong cách tốn ít chi phí xây dựng nhất trong năm phong cách, vì phần lớn hiệu quả đến từ cây và vật liệu bề mặt.'))
P(('lead','Ưu điểm với mặt bằng 70m²'))
P(('ul',[
  '**Chia khu mà không xây tường.** Một hàng bồn cây cao 1,2m tách được khu làm việc với lối đi mà không chắn sáng, không tính là vách.',
  '**Tạo điểm nhấn rẻ nhất.** Một mảng tường cây 2 – 4m² ở lễ tân gây ấn tượng mạnh hơn nhiều so với ốp đá cùng diện tích, chi phí thấp hơn hẳn.',
  '**Cải thiện cảm nhận không khí.** Ở văn phòng nhỏ, mật độ người trên mét vuông cao nên yếu tố này cảm nhận rõ hơn văn phòng lớn.',
  '**Phù hợp định vị thương hiệu bền vững.** Khách và đối tác nhìn thấy ngay khi bước vào.']))
P(('p','Xét cùng một nhiệm vụ là tách khu làm việc chung khỏi lối đi trên mặt bằng 70m²: một vách thạch cao cao 1,2m dài 5m chiếm khoảng 0,5m² sàn nhưng chặn tầm nhìn và cần thi công tại chỗ; một dãy bồn cây cùng chiều dài chiếm khoảng 0,75m² sàn, không chặn sáng, lắp trong một buổi và tháo dời được khi đổi bố cục. Chênh lệch 0,25m² là không đáng kể so với việc giữ được ánh sáng tự nhiên cho toàn bộ khu làm việc — vốn là thứ văn phòng 70m² thiếu nhất.'))
P(('img','a70-08','Văn phòng 70m2 phong cách xanh: cây leo trần, mảng tường cây kết hợp lam gỗ ở khu tiếp khách'))
P(('img','a70-07','Văn phòng ấm áp với đường vòm kiến trúc màu vàng và cây xanh, tràn ngập ánh sáng tự nhiên (Nguồn: Internet)'))
P(('img','b80-31','Cây xanh là cách tạo điểm nhấn tiết kiệm nhất vì không phải xây thêm gì (Ảnh tham khảo)'))
P(('img','b80-32','Tường cây 2 – 4m² đặt đúng chỗ khách nhìn thấy đầu tiên khi bước vào (Ảnh tham khảo)'))
P(('img','b80-33','Giá sắt kết hợp chậu cây làm vách ngăn — chia khu mà không chắn sáng (Ảnh tham khảo)'))

# ---------- 4.4 KHONG GIAN MO ----------
P(('h3','4.4. Mẫu thiết kế văn phòng 70m2 không gian mở (Open Office)'))
P(('p','Không gian mở bỏ hẳn vách ngăn cố định giữa các bộ phận, chỉ giữ lại một đến hai phòng kín thực sự cần thiết. Việc phân vùng do nội thất đảm nhiệm: bàn cụm, tủ thấp, thảm, thay đổi cao độ trần hoặc màu sàn. Với văn phòng 70m2, đây là phương án cho ra số chỗ ngồi cao nhất trong năm phong cách.'))
P(('lead','Ưu điểm với mặt bằng 70m²'))
P(('ul',[
  '**Nhiều chỗ ngồi nhất.** Bỏ được phần diện tích tường và hành lang phụ mà mặt bằng chia phòng buộc phải có.',
  '**Dễ đổi bố cục.** Tăng hay giảm nhân sự chỉ cần kê lại bàn, không phải đập vách.',
  '**Tăng kết nối giữa các bộ phận.** Ở quy mô dưới 15 người, cả đội nhìn thấy nhau là ưu thế vận hành.',
  '**Ánh sáng tự nhiên đi được sâu vào trong.** Không có vách chặn nên vị trí ngồi trong cùng vẫn đủ sáng.']))
P(('p','Trên mặt bằng 70m², phương án chia ba phòng kín cần khoảng 8 – 10m² cho riêng phần tường, vách và hành lang dẫn vào các phòng đó. Bỏ hết phòng kín, phần diện tích này quay về khu làm việc chung — tương đương thêm 2 chỗ ngồi ở mức 5m²/người, hoặc 3 chỗ ở mức tiết kiệm. Đổi lại là tiếng ồn: cần trần tiêu âm hoặc tấm tiêu âm treo phía trên khu làm việc, chi phí khoảng 300.000 – 600.000đ/m² trần — một khoản nhỏ so với giá trị của 2 – 3 chỗ ngồi thêm.'))
P(('img','a70-11','Văn phòng 70m2 không gian mở: trần để lộ hệ kỹ thuật, bàn kê thành cụm, không vách ngăn cố định'))
P(('img','a70-21','Khu làm việc mở trong văn phòng 70m2, tủ thấp thay vách ngăn để ánh sáng đi được vào sâu'))
P(('img','b80-21','Sàn mở hoàn toàn cho số chỗ ngồi tối đa, bù lại cần trần tiêu âm và thảm để giảm ồn (Ảnh tham khảo)'))
P(('img','b80-25','Bàn dài dùng chung bỏ được khoảng hở giữa các bàn — cách kê tiết kiệm diện tích nhất (Ảnh tham khảo)'))
P(('img','b80-40','Không bàn cố định, tủ khóa cá nhân thay ngăn kéo nên cùng diện tích phục vụ được nhiều người hơn (Ảnh tham khảo)'))

# ---------- 4.5 CONG NGHIEP ----------
P(('h3','4.5. Mẫu thiết kế văn phòng 70m2 phong cách công nghiệp (Industrial)'))
P(('p','Phong cách công nghiệp giữ nguyên vẻ thô của kết cấu: trần bê tông để mộc lộ hệ ống gió và máng điện, tường gạch hoặc bê tông trần, khung thép sơn đen, sàn gỗ hoặc bê tông mài. Điểm quan trọng với văn phòng 70m2 là phong cách này chỉ phát huy khi trần cao trên 3m — trần thấp mà để lộ hệ kỹ thuật sẽ gây cảm giác nặng và bí.'))
P(('lead','Ưu điểm với mặt bằng 70m²'))
P(('ul',[
  '**"Ăn gian" được chiều cao.** Bỏ trần thạch cao trả lại 30 – 50cm chiều cao thông thủy, mặt bằng 70m² đỡ cảm giác chật.',
  '**Cắt được một hạng mục thi công.** Không làm trần giả nghĩa là bớt cả phần khung xương và hoàn thiện.',
  '**Tạo dấu ấn riêng.** Hợp doanh nghiệp sáng tạo, startup muốn khác với khuôn mẫu văn phòng truyền thống.',
  '**Bền, ít phải bảo trì bề mặt.** Vật liệu thô ít lộ dấu sử dụng hơn bề mặt sơn phẳng.']))
P(('p','Trần thạch cao khung xương cho 70m² thường tốn khoảng 250.000 – 400.000đ/m², tức 17 – 28 triệu cho cả sàn. Bỏ trần giả và chỉ sơn hệ kỹ thuật màu tối tiết kiệm phần lớn khoản này, đồng thời trả lại 30 – 50cm chiều cao. Đổi lại, hệ điện và điều hòa phải đi gọn và thẳng hàng vì không còn chỗ giấu — đây là hạng mục cần chốt bản vẽ kỹ trước khi thi công, và là lý do phong cách này chỉ nên chọn khi trần thô cao từ 3m trở lên.'))
P(('img','a70-03','Văn phòng 70m2 phong cách công nghiệp: trần cao để lộ hệ kỹ thuật, khung thép và hệ cửa kính lớn'))
P(('img','a70-10','Trần dầm gỗ để mộc kết hợp bàn dài dùng chung — cách khai thác chiều cao cho văn phòng nhỏ'))
P(('img','b80-17','Gạch mộc, gác lửng khung thép và sàn gỗ sẫm tạo dấu ấn riêng cho doanh nghiệp sáng tạo (Ảnh tham khảo)'))
P(('img','b80-23','Trần để mộc giúp ăn gian chiều cao, nhưng chỉ hiệu quả khi trần cao trên 3m (Ảnh tham khảo)'))
P(('img','b80-28','Vách kính khung thép đen cho doanh nghiệp cần phòng riêng mà không muốn mặt bằng bị cắt vụn (Ảnh tham khảo)'))
